import org.junit.Test;
import org.jsoup.nodes.TextNode;
import org.mockito.Mockito;

public class TextNodeTest {

    @Test
    public void nodeName_test() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals("text", node.nodeName());
    }

    @Test
    public void textTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(text, node.text());
        Mockito.when(node.toString()).thenReturn(text);
    }

    @Test
    public void getWholeTextTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals("Hello World", node.getWholeText());
        Mockito.when(node.toString()).thenReturn(text);
    }

    @Test
    public void isBlankTest() {
        String text = "";
        TextNode node = new TextNode(text);
        assertTrue(node.isBlank());
        Mockito.when(node.toString()).thenReturn(text);
    }

    @Test
    public void splitTextTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals(4, node.splitText(0));
        Mockito.when(node.toString()).thenReturn("Hello World");
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        // No mock needed for this method
        String text = "Hello World";
        TextNode node = new TextNode(text);
        node.outerHtmlHead(Mockito.mock(Appendable.class), 0, Mockito.mock(Document.OutputSettings.class));
    }

    @Test
    public void outerHtmlTailTest() {
        // No mock needed for this method
        String text = "Hello World";
        TextNode node = new TextNode(text);
        node.outerHtmlTail(Mockito.mock(Appendable.class), 0, Mockito.mock(Document.OutputSettings.class));
    }

    @Test
    public void toStringTest() {
        String text = "Hello World";
        TextNode node = new TextNode(text);
        assertEquals("text", node.toString());
    }
}
